[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Leap Studio — Your Reinvention and Experience Partner</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    :root {
      --bg-primary: #0A0A0A;
      --bg-elevated: #141414;
      --bg-card: #1A1A1A;
      --bg-card-hover: #222222;
      --text-primary: #FFFFFF;
      --text-secondary: #A0A0A0;
      --text-muted: #666666;
      --accent: #4A9EFF;
      --accent-warm: #E8A838;
      --accent-glow: rgba(74, 158, 255, 0.15);
      --border: #2A2A2A;
      --radius: 12px;
      --radius-sm: 8px;
      --transition: 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
      --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    }

    html { scroll-behavior: smooth; font-size: 16px; }

    body {
      font-family: var(--font);
      background: var(--bg-primary);
      color: var(--text-primary);
      line-height: 1.6;
      overflow-x: hidden;
      -webkit-font-smoothing: antialiased;
    }

    a { color: inherit; text-decoration: none; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; color: inherit; }
    img { display: block; max-width: 100%; }

    .container { max-width: 1280px; margin: 0 auto; padding: 0 24px; }

    /* ── NAV ── */
    .nav {
      position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
      padding: 0 24px; height: 72px;
      display: flex; align-items: center; justify-content: space-between;
      background: rgba(10, 10, 10, 0.85);
      backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px);
      border-bottom: 1px solid var(--border);
      transition: background var(--transition);
    }
    .nav-brand {
      font-size: 1.25rem; font-weight: 800; letter-spacing: -0.02em;
      display: flex; align-items: center; gap: 8px;
    }
    .nav-brand span { color: var(--accent); }
    .nav-links { display: flex; align-items: center; gap: 32px; }
    .nav-links a {
      font-size: 0.875rem; font-weight: 500; color: var(--text-secondary);
      transition: color var(--transition); position: relative;
    }
    .nav-links a:hover { color: var(--text-primary); }
    .nav-links a::after {
      content: ''; position: absolute; bottom: -4px; left: 0; width: 0; height: 1px;
      background: var(--accent); transition: width var(--transition);
    }
    .nav-links a:hover::after { width: 100%; }

    .lang-selector { position: relative; }
    .lang-btn {
      display: flex; align-items: center; gap: 6px;
      font-size: 0.8rem; font-weight: 500; color: var(--text-secondary);
      padding: 6px 12px; border: 1px solid var(--border); border-radius: 20px;
      transition: all var(--transition);
    }
    .lang-btn:hover { border-color: var(--text-muted); color: var(--text-primary); }
    .lang-btn svg { width: 14px; height: 14px; transition: transform var(--transition); }
    .lang-selector.open .lang-btn svg { transform: rotate(180deg); }
    .lang-dropdown {
      position: absolute; top: calc(100% + 8px); right: 0;
      background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-sm);
      padding: 6px; min-width: 160px; opacity: 0; visibility: hidden;
      transform: translateY(-8px); transition: all var(--transition);
      box-shadow: 0 16px 48px rgba(0,0,0,0.4);
    }
    .lang-selector.open .lang-dropdown { opacity: 1; visibility: visible; transform: translateY(0); }
    .lang-dropdown a {
      display: block; padding: 8px 14px; border-radius: 6px;
      font-size: 0.85rem; color: var(--text-secondary); transition: all var(--transition);
    }
    .lang-dropdown a:hover, .lang-dropdown a.active { background: var(--bg-elevated); color: var(--text-primary); }

    .nav-hamburger {
      display: none; flex-direction: column; gap: 5px;
      padding: 8px; cursor: pointer;
    }
    .nav-hamburger span {
      display: block; width: 22px; height: 2px; background: var(--text-primary);
      transition: all var(--transition); border-radius: 2px;
    }
    .nav-hamburger.open span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
    .nav-hamburger.open span:nth-child(2) { opacity: 0; }
    .nav-hamburger.open span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

    .mobile-menu {
      display: none; position: fixed; top: 72px; left: 0; right: 0; bottom: 0;
      background: var(--bg-primary); padding: 32px 24px; z-index: 999;
      flex-direction: column; gap: 0; opacity: 0; transform: translateY(-10px);
      transition: all var(--transition);
    }
    .mobile-menu.open { display: flex; opacity: 1; transform: translateY(0); }
    .mobile-menu a {
      padding: 16px 0; font-size: 1.25rem; font-weight: 500;
      color: var(--text-secondary); border-bottom: 1px solid var(--border);
      transition: color var(--transition);
    }
    .mobile-menu a:hover { color: var(--text-primary); }

    /* ── HERO ── */
    .hero {
      padding-top: 72px; min-height: 100vh; display: flex; align-items: center;
      position: relative; overflow: hidden;
    }
    .hero::before {
      content: ''; position: absolute; top: -200px; right: -200px;
      width: 600px; height: 600px; border-radius: 50%;
      background: radial-gradient(circle, var(--accent-glow), transparent 70%);
      pointer-events: none;
    }
    .hero .container { width: 100%; padding: 60px 24px; }
    .hero-carousel { position: relative; }
    .hero-slides { position: relative; min-height: 420px; }
    .hero-slide {
      position: absolute; top: 0; left: 0; width: 100%;
      opacity: 0; transform: translateX(40px);
      transition: opacity 0.6s ease, transform 0.6s ease;
      pointer-events: none;
    }
    .hero-slide.active { opacity: 1; transform: translateX(0); pointer-events: auto; }
    .hero-label {
      display: inline-flex; align-items: center; gap: 8px;
      font-size: 0.75rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.12em;
      color: var(--accent); margin-bottom: 20px;
    }
    .hero-label::before {
      content: ''; width: 24px; height: 1px; background: var(--accent);
    }
    .hero-title {
      font-size: clamp(2.5rem, 6vw, 4.5rem); font-weight: 800; line-height: 1.05;
      letter-spacing: -0.03em; margin-bottom: 20px; max-width: 800px;
    }
    .hero-desc {
      font-size: 1.125rem; color: var(--text-secondary); max-width: 560px;
      line-height: 1.7; margin-bottom: 32px;
    }
    .hero-cta {
      display: inline-flex; align-items: center; gap: 10px;
      padding: 14px 32px; background: var(--accent); color: #000;
      font-size: 0.9rem; font-weight: 700; border-radius: 50px;
      transition: all var(--transition);
    }
    .hero-cta:hover { background: #6BB3FF; transform: translateY(-2px); box-shadow: 0 8px 30px rgba(74,158,255,0.3); }
    .hero-cta svg { width: 16px; height: 16px; transition: transform var(--transition); }
    .hero-cta:hover svg { transform: translateX(4px); }

    .hero-nav {
      display: flex; align-items: center; gap: 16px; margin-top: 56px;
    }
    .hero-nav-btn {
      width: 48px; height: 48px; border-radius: 50%;
      border: 1px solid var(--border); display: flex; align-items: center; justify-content: center;
      transition: all var(--transition); color: var(--text-secondary);
    }
    .hero-nav-btn:hover { border-color: var(--accent); color: var(--accent); background: var(--accent-glow); }
    .hero-nav-btn svg { width: 18px; height: 18px; }
    .hero-dots { display: flex; gap: 8px; margin-left: 8px; }
    .hero-dot {
      width: 8px; height: 8px; border-radius: 50%; background: var(--text-muted);
      transition: all var(--transition); cursor: pointer;
    }
    .hero-dot.active { background: var(--accent); width: 28px; border-radius: 4px; }

    .hero-counter {
      margin-left: auto; font-size: 0.85rem; color: var(--text-muted);
      font-variant-numeric: tabular-nums;
    }
    .hero-counter .current { color: var(--text-primary); font-weight: 600; }

    /* ── SECTION SHARED ── */
    .section { padding: 100px 0; position: relative; }
    .section-header { margin-bottom: 56px; }
    .section-label {
      font-size: 0.75rem; font-weight: 600; text-transform: uppercase;
      letter-spacing: 0.12em; color: var(--accent); margin-bottom: 16px;
    }
    .section-title {
      font-size: clamp(2rem, 4vw, 3rem); font-weight: 800; letter-spacing: -0.02em;
      line-height: 1.1; max-width: 640px;
    }
    .section-subtitle {
      font-size: 1.1rem; color: var(--text-secondary); max-width: 520px;
      margin-top: 16px; line-height: 1.7;
    }

    /* ── TEAM ── */
    .team-section { background: var(--bg-elevated); }
    .region-tabs {
      display: flex; gap: 4px; margin-bottom: 40px;
      background: var(--bg-primary); border-radius: 50px; padding: 4px;
      width: fit-content;
    }
    .region-tab {
      padding: 10px 24px; border-radius: 50px; font-size: 0.875rem; font-weight: 600;
      color: var(--text-secondary); transition: all var(--transition);
    }
    .region-tab:hover { color: var(--text-primary); }
    .region-tab.active { background: var(--accent); color: #000; }

    .team-carousel-wrapper { position: relative; overflow: hidden; }
    .team-carousel {
      display: flex; gap: 24px; transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
      cursor: grab;
    }
    .team-carousel.dragging { cursor: grabbing; transition: none; }
    .team-card {
      min-width: 340px; max-width: 340px; background: var(--bg-card);
      border-radius: var(--radius); overflow: hidden; flex-shrink: 0;
      border: 1px solid var(--border); transition: all var(--transition);
    }
    .team-card:hover { border-color: #3A3A3A; transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.3); }
    .team-card-photo {
      width: 100%; height: 240px; background: linear-gradient(135deg, #2a2a2a, #1a1a1a);
      display: flex; align-items: center; justify-content: center;
      position: relative; overflow: hidden;
    }
    .team-card-photo .photo-placeholder {
      width: 80px; height: 80px; border-radius: 50%;
      background: linear-gradient(135deg, var(--accent), var(--accent-warm));
      opacity: 0.6;
    }
    .team-card-body { padding: 24px; }
    .team-card-quote {
      font-size: 0.95rem; line-height: 1.6; color: var(--text-secondary);
      font-style: italic; margin-bottom: 20px; min-height: 80px;
    }
    .team-card-name { font-size: 1.05rem; font-weight: 700; margin-bottom: 4px; }
    .team-card-title { font-size: 0.85rem; color: var(--text-muted); margin-bottom: 16px; }
    .team-card-cta {
      display: inline-flex; align-items: center; gap: 6px;
      font-size: 0.85rem; font-weight: 600; color: var(--accent);
      transition: all var(--transition);
    }
    .team-card-cta:hover { gap: 10px; }
    .team-card-cta svg { width: 14px; height: 14px; }

    .carousel-nav-arrows {
      display: flex; gap: 12px; margin-top: 32px;
    }
    .carousel-arrow {
      width: 44px; height: 44px; border-radius: 50%;
      border: 1px solid var(--border); display: flex; align-items: center; justify-content: center;
      transition: all var(--transition); color: var(--text-secondary);
    }
    .carousel-arrow:hover { border-color: var(--accent); color: var(--accent); background: var(--accent-glow); }
    .carousel-arrow svg { width: 16px; height: 16px; }

    /* ── WORK ── */
    .work-section { overflow: hidden; }
    .work-carousel-wrapper { position: relative; }
    .work-carousel {
      display: flex; gap: 24px; overflow-x: auto; scroll-snap-type: x mandatory;
      scrollbar-width: none; -ms-overflow-style: none;
      padding-bottom: 8px; cursor: grab;
    }
    .work-carousel::-webkit-scrollbar { display: none; }
    .work-carousel.dragging { cursor: grabbing; scroll-snap-type: none; }
    .work-card {
      min-width: 380px; max-width: 380px; flex-shrink: 0; scroll-snap-align: start;
      border-radius: var(--radius); overflow: hidden; position: relative;
      transition: all var(--transition); cursor: pointer;
      border: 1px solid var(--border);
    }
    .work-card:hover { transform: translateY(-4px); border-color: #3A3A3A; box-shadow: 0 12px 40px rgba(0,0,0,0.3); }
    .work-card-img {
      width: 100%; height: 260px; background: linear-gradient(135deg, #1e2a3a, #1a1a2a);
      position: relative; overflow: hidden;
    }
    .work-card-img .work-img-pattern {
      position: absolute; inset: 0; opacity: 0.15;
      background: repeating-linear-gradient(45deg, transparent, transparent 20px, var(--accent) 20px, var(--accent) 21px);
    }
    .work-card-client {
      position: absolute; bottom: 16px; left: 16px;
      font-size: 0.7rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.1em;
      background: rgba(0,0,0,0.6); backdrop-filter: blur(8px);
      padding: 6px 12px; border-radius: 4px;
    }
    .work-card-body { padding: 24px; background: var(--bg-card); }
    .work-card-title { font-size: 1.05rem; font-weight: 700; margin-bottom: 10px; line-height: 1.3; }
    .work-card-quote {
      font-size: 0.85rem; color: var(--text-secondary); line-height: 1.6;
      font-style: italic;
    }
    .work-card-quote cite {
      display: block; margin-top: 8px; font-style: normal;
      color: var(--text-muted); font-size: 0.8rem;
    }

    /* ── CTA BANNER ── */
    .cta-banner {
      padding: 80px 0; text-align: center; position: relative; overflow: hidden;
    }
    .cta-banner::before {
      content: ''; position: absolute; bottom: -100px; left: 50%; transform: translateX(-50%);
      width: 500px; height: 500px; border-radius: 50%;
      background: radial-gradient(circle, rgba(232,168,56,0.1), transparent 70%);
      pointer-events: none;
    }
    .cta-banner-title {
      font-size: clamp(2rem, 4vw, 3.5rem); font-weight: 800; letter-spacing: -0.02em;
      margin-bottom: 16px;
    }
    .cta-banner-body {
      font-size: 1.1rem; color: var(--text-secondary); max-width: 560px;
      margin: 0 auto 32px; line-height: 1.7;
    }
    .cta-banner-btn {
      display: inline-flex; align-items: center; gap: 10px;
      padding: 16px 36px; background: var(--accent-warm); color: #000;
      font-size: 0.95rem; font-weight: 700; border-radius: 50px;
      transition: all var(--transition);
    }
    .cta-banner-btn:hover { background: #F0B84A; transform: translateY(-2px); box-shadow: 0 8px 30px rgba(232,168,56,0.3); }
    .cta-banner-btn svg { width: 16px; height: 16px; }

    /* ── HOW WE WORK ── */
    .how-section { background: var(--bg-elevated); }
    .how-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center; }
    .how-content {}
    .how-headline {
      font-size: clamp(2rem, 4vw, 3rem); font-weight: 800; line-height: 1.1;
      letter-spacing: -0.02em; margin-bottom: 20px;
    }
    .how-body {
      font-size: 1.05rem; color: var(--text-secondary); line-height: 1.7; margin-bottom: 32px;
    }
    .how-cta {
      display: inline-flex; align-items: center; gap: 10px;
      font-size: 0.95rem; font-weight: 600; color: var(--accent);
      transition: all var(--transition);
    }
    .how-cta:hover { gap: 14px; }
    .how-cta svg { width: 16px; height: 16px; }
    .how-visual {
      display: flex; align-items: center; justify-content: center;
      height: 360px; border-radius: var(--radius); position: relative;
      background: linear-gradient(135deg, var(--bg-card), var(--bg-primary));
      border: 1px solid var(--border); overflow: hidden;
    }
    .how-visual-pattern {
      position: absolute; inset: 0; opacity: 0.06;
      background: repeating-conic-gradient(var(--accent) 0% 25%, transparent 0% 50%) 50% / 40px 40px;
    }
    .how-visual-text {
      font-size: 6rem; font-weight: 900; color: var(--accent); opacity: 0.12;
      letter-spacing: -0.04em; position: relative; z-index: 1;
    }

    /* ── INSIGHTS ── */
    .insights-grid {
      display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px;
    }
    .insight-card {
      background: var(--bg-card); border-radius: var(--radius); overflow: hidden;
      border: 1px solid var(--border); transition: all var(--transition);
    }
    .insight-card:hover { border-color: #3A3A3A; transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.3); }
    .insight-thumb {
      height: 180px; background: linear-gradient(135deg, #1a2030, #1a1a2a);
      display: flex; align-items: center; justify-content: center;
      position: relative; overflow: hidden;
    }
    .insight-thumb-icon {
      font-size: 2.5rem; opacity: 0.15;
    }
    .insight-type-badge {
      position: absolute; top: 12px; left: 12px;
      font-size: 0.65rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.1em;
      background: rgba(0,0,0,0.5); backdrop-filter: blur(8px);
      padding: 4px 10px; border-radius: 4px; color: var(--accent);
    }
    .insight-body { padding: 20px; }
    .insight-title { font-size: 1rem; font-weight: 700; line-height: 1.4; margin-bottom: 16px; }
    .insight-cta {
      font-size: 0.85rem; font-weight: 600; color: var(--accent);
      display: inline-flex; align-items: center; gap: 6px;
      transition: all var(--transition);
    }
    .insight-cta:hover { gap: 10px; }
    .insight-cta svg { width: 14px; height: 14px; }

    /* ── PRINCIPLES ── */
    .principles-section { background: var(--bg-elevated); }
    .principles-grid {
      display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px;
    }
    .principle-card {
      padding: 40px; background: var(--bg-card); border-radius: var(--radius);
      border: 1px solid var(--border); transition: all var(--transition);
      position: relative; overflow: hidden;
    }
    .principle-card::before {
      content: ''; position: absolute; top: 0; left: 0; width: 3px; height: 0;
      background: var(--accent); transition: height var(--transition);
    }
    .principle-card:hover::before { height: 100%; }
    .principle-card:hover { border-color: #3A3A3A; }
    .principle-number {
      font-size: 3rem; font-weight: 900; color: var(--accent); opacity: 0.15;
      margin-bottom: 12px; line-height: 1;
    }
    .principle-title { font-size: 1.2rem; font-weight: 700; margin-bottom: 12px; }
    .principle-desc { font-size: 0.95rem; color: var(--text-secondary); line-height: 1.7; }

    /* ── FOOTER ── */
    .footer { padding: 80px 0 32px; border-top: 1px solid var(--border); }
    .footer-top { display: grid; grid-template-columns: 1fr 1fr; gap: 48px; margin-bottom: 64px; }
    .footer-cta-block {}
    .footer-cta-title { font-size: 1.5rem; font-weight: 700; margin-bottom: 12px; line-height: 1.3; }
    .footer-cta-body { font-size: 0.95rem; color: var(--text-secondary); margin-bottom: 20px; line-height: 1.6; }
    .footer-cta-btn {
      display: inline-flex; align-items: center; gap: 8px;
      padding: 12px 28px; border-radius: 50px; font-size: 0.9rem; font-weight: 600;
      transition: all var(--transition);
    }
    .footer-cta-btn.primary { background: var(--accent); color: #000; }
    .footer-cta-btn.primary:hover { background: #6BB3FF; }
    .footer-cta-btn.secondary { border: 1px solid var(--border); color: var(--text-secondary); }
    .footer-cta-btn.secondary:hover { border-color: var(--text-muted); color: var(--text-primary); }

    .footer-middle { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 48px; padding-bottom: 48px; border-bottom: 1px solid var(--border); }
    .footer-brand { font-size: 1.25rem; font-weight: 800; margin-bottom: 8px; }
    .footer-brand span { color: var(--accent); }
    .footer-tagline { font-size: 0.85rem; color: var(--text-muted); }
    .footer-links { display: flex; gap: 32px; }
    .footer-links a { font-size: 0.875rem; color: var(--text-secondary); transition: color var(--transition); }
    .footer-links a:hover { color: var(--text-primary); }

    .footer-bottom { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 16px; }
    .footer-legal { font-size: 0.8rem; color: var(--text-muted); display: flex; flex-wrap: wrap; gap: 16px; align-items: center; }
    .footer-legal a { color: var(--text-muted); transition: color var(--transition); }
    .footer-legal a:hover { color: var(--text-secondary); }
    .footer-legal .dot { width: 3px; height: 3px; border-radius: 50%; background: var(--text-muted); }

    /* ── COOKIE BANNER ── */
    .cookie-banner {
      position: fixed; bottom: 0; left: 0; right: 0; z-index: 2000;
      background: var(--bg-card); border-top: 1px solid var(--border);
      padding: 20px 24px; display: flex; align-items: center; justify-content: center; gap: 24px;
      transform: translateY(100%); transition: transform 0.4s ease;
      box-shadow: 0 -8px 40px rgba(0,0,0,0.4);
    }
    .cookie-banner.visible { transform: translateY(0); }
    .cookie-text { font-size: 0.875rem; color: var(--text-secondary); max-width: 560px; line-height: 1.5; }
    .cookie-text a { color: var(--accent); }
    .cookie-actions { display: flex; gap: 10px; flex-shrink: 0; }
    .cookie-btn {
      padding: 8px 20px; border-radius: 50px; font-size: 0.8rem; font-weight: 600;
      transition: all var(--transition); white-space: nowrap;
    }
    .cookie-btn.accept { background: var(--accent); color: #000; }
    .cookie-btn.accept:hover { background: #6BB3FF; }
    .cookie-btn.decline { border: 1px solid var(--border); color: var(--text-secondary); }
