    /* ── DATA ── */
    const teamData = {
      'north-america': [
        { name: 'Denice Alvarez', title: 'Office Manager', office: 'New York', quote: 'As the Office Manager, I engage with teams from every discipline, and have learned so much through my day-to-day interactions with my fellow leapers.', gradient: '135deg, #1a3a5c, #0a1a2c' },
