      ],
    };

    const workData = [
      { client: 'Unilever', title: 'Creating Consumer Insights at Scale', quote: 'The PDC provides insight not only to marketing, but also to supply chain, R&D, HR and finance. Thanks to the collaboration with Leap Studio we now have the capability to provide insight and action all across the organisation.', cite: 'Alex Owens, VP, Global Head of People Data Centres, Unilever', gradient: '135deg, #1e2a3a, #0e1a2a' },
      { client: 'IKEA Retail (Ingka Group)', title: 'Deepening Customer Engagement', quote: null, gradient: '135deg, #2a1e3a, #1a0e2a' },
      { client: 'Volvo Group', title: 'Harnessing Data for Leaner and Greener Future of Mobility', quote: null, gradient: '135deg, #1e3a2a, #0e2a1a' },
      { client: 'Chase Payment Solutions', title: 'Modernizing the Point-of-Sale Experience', quote: null, gradient: '135deg, #3a2a1e, #2a1a0e' },
      { client: 'Tiffany & Co.', title: 'Reimagining Luxury Craftsmanship', quote: 'We valued the truly collaborative process from conception to delivery. The resulting experience beautifully emphasizes our core brand codes of craftsmanship and heritage, while effectively leveraging new AI technologies.', cite: 'Thomas Arnold, Digital Experience Design & Innovation Director', gradient: '135deg, #2a1e2a, #1a0e1a' },
      { client: 'Majid Al Futtaim / Carrefour', title: 'Helping Healthier Habits Stick', quote: "Our 'Pick Your 5' framework, based on your behavior change strategy, is going to be instrumental in driving positive outcomes.", cite: 'Sheila Chaiban, Global CMO', gradient: '135deg, #1e2a2a, #0e1a1a' },
      { client: 'Leap Studio', title: 'Designing Robots for Human Spaces', quote: null, gradient: '135deg, #2a2a1e, #1a1a0e' },
      { client: 'Destination NSW', title: 'Harboring Culture Year-Round', quote: null, gradient: '135deg, #1e1e3a, #0e0e2a' },
    ];

    const insightsData = [
      { type: 'Podcast', title: 'Ep. 58 — When Human Connection Meets AI', cta: 'Listen' },
      { type: 'Podcast', title: 'Ep. 57 — Writing the Future of AI', cta: 'Listen' },
      { type: 'Article', title: 'Amplifying Clinical Care with AI', cta: 'Read' },
      { type: 'Podcast', title: 'Ep. 56 — The Future of Customer Experience', cta: 'Listen' },
      { type: 'Article', title: 'Next-Gen Contact Centers: Powered by AI', cta: 'Read' },
      { type: 'Article', title: 'The AI-Empowered Marketer', cta: 'Read' },
    ];

    /* ── HERO CAROUSEL ── */
    const heroSlides = document.querySelectorAll('.hero-slide');
    const heroDots = document.getElementById('heroDots');
    const heroCurrent = document.getElementById('heroCurrent');
    let heroIndex = 0;
    let heroAutoTimer;

    heroSlides.forEach((_, i) => {
      const dot = document.createElement('div');
      dot.className = 'hero-dot' + (i === 0 ? ' active' : '');
      dot.addEventListener('click', () => goHero(i));
      heroDots.appendChild(dot);
    });

    function goHero(idx) {
      heroSlides[heroIndex].classList.remove('active');
      heroDots.children[heroIndex].classList.remove('active');
      heroIndex = (idx + heroSlides.length) % heroSlides.length;
      heroSlides[heroIndex].classList.add('active');
      heroDots.children[heroIndex].classList.add('active');
      heroCurrent.textContent = String(heroIndex + 1).padStart(2, '0');
      resetHeroAuto();
    }

    document.getElementById('heroPrev').addEventListener('click', () => goHero(heroIndex - 1));
    document.getElementById('heroNext').addEventListener('click', () => goHero(heroIndex + 1));

    function resetHeroAuto() {
      clearInterval(heroAutoTimer);
      heroAutoTimer = setInterval(() => goHero(heroIndex + 1), 6000);
    }
    resetHeroAuto();

    /* ── TEAM CAROUSEL ── */
    const teamCarousel = document.getElementById('teamCarousel');
    let currentRegion = 'north-america';
    let teamOffset = 0;

    function renderTeam(region) {
      currentRegion = region;
      teamOffset = 0;
      const members = teamData[region];
      teamCarousel.style.transition = 'none';
      teamCarousel.style.transform = 'translateX(0)';
      teamCarousel.innerHTML = members.map(m => `
        <div class="team-card">
          <div class="team-card-photo" style="background:linear-gradient(${m.gradient})">
            <div class="photo-placeholder"></div>
          </div>
          <div class="team-card-body">
            <div class="team-card-quote">"${m.quote}"</div>
            <div class="team-card-name">${m.name}</div>
            <div class="team-card-title">${m.title}</div>
            <a href="#" class="team-card-cta">Contact Leap Studio ${m.office} <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M5 12h14M12 5l7 7-7 7"/></svg></a>
          </div>
        </div>
      `).join('');
      updateTeamArrows();
    }

    function updateTeamArrows() {
      const maxOffset = Math.max(0, (teamCarousel.children.length * 364) - teamCarousel.parentElement.offsetWidth);
      document.getElementById('teamPrev').style.opacity = teamOffset <= 0 ? '0.3' : '1';
      document.getElementById('teamNext').style.opacity = teamOffset >= maxOffset ? '0.3' : '1';
    }

    document.getElementById('teamPrev').addEventListener('click', () => {
      teamOffset = Math.max(0, teamOffset - 364);
      teamCarousel.style.transition = 'transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
      teamCarousel.style.transform = `translateX(-${teamOffset}px)`;
      updateTeamArrows();
    });

    document.getElementById('teamNext').addEventListener('click', () => {
      const maxOffset = Math.max(0, (teamCarousel.children.length * 364) - teamCarousel.parentElement.offsetWidth);
      teamOffset = Math.min(maxOffset, teamOffset + 364);
      teamCarousel.style.transition = 'transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
      teamCarousel.style.transform = `translateX(-${teamOffset}px)`;
      updateTeamArrows();
    });

    // Region tabs
    document.getElementById('regionTabs').addEventListener('click', e => {
      if (!e.target.classList.contains('region-tab')) return;
      document.querySelectorAll('.region-tab').forEach(t => t.classList.remove('active'));
      e.target.classList.add('active');
      renderTeam(e.target.dataset.region);
    });

    renderTeam('north-america');

    // Team drag scroll
    let teamDragging = false, teamStartX, teamStartOffset;
    teamCarousel.addEventListener('mousedown', e => {
      teamDragging = true; teamCarousel.classList.add('dragging');
      teamStartX = e.clientX; teamStartOffset = teamOffset;
    });
    document.addEventListener('mousemove', e => {
      if (!teamDragging) return;
      const diff = teamStartX - e.clientX;
      const maxOffset = Math.max(0, (teamCarousel.children.length * 364) - teamCarousel.parentElement.offsetWidth);
      teamOffset = Math.max(0, Math.min(maxOffset, teamStartOffset + diff));
      teamCarousel.style.transform = `translateX(-${teamOffset}px)`;
    });
    document.addEventListener('mouseup', () => {
      teamDragging = false; teamCarousel.classList.remove('dragging');
    });

    // Touch support for team
    teamCarousel.addEventListener('touchstart', e => {
      teamDragging = true; teamCarousel.classList.add('dragging');
      teamStartX = e.touches[0].clientX; teamStartOffset = teamOffset;
    }, { passive: true });
    teamCarousel.addEventListener('touchmove', e => {
      if (!teamDragging) return;
      const diff = teamStartX - e.touches[0].clientX;
      const maxOffset = Math.max(0, (teamCarousel.children.length * 364) - teamCarousel.parentElement.offsetWidth);
      teamOffset = Math.max(0, Math.min(maxOffset, teamStartOffset + diff));
      teamCarousel.style.transform = `translateX(-${teamOffset}px)`;
    }, { passive: true });
    teamCarousel.addEventListener('touchend', () => {
      teamDragging = false; teamCarousel.classList.remove('dragging');
    });

    /* ── WORK CAROUSEL ── */
    const workCarousel = document.getElementById('workCarousel');
